<?php
/**
 * Proof — every tool of the records server answers what its row of the surface says, in the Phase 4 world (tests/phase4/world.sql over Phase 2's SMOKE book): the filters do what they claim, a name resolves (the registry's
 * resolver calls a find_* tool with `q` alone and wants ONE row for an exact name), paging reports `total` and `truncated`, money is a string with two decimals, the functions' answers pass through unchanged, the errors are
 * words. The wall is wall.php's; the shares' are shares.php's.
 */
require __DIR__ . '/lib.php';
$w = p4_world();
$today = date('Y-m-d'); $back = date('Y-m-d', time() - 60 * 86400); $week = date('Y-m-d', time() + 7 * 86400); $monthStart = date('Y-m-01');
$T = static fn (int $m, string $t, array $a = []) => tool($m, $t, $a);
$R = static fn (int $m, string $t, array $a = []) => trows($m, $t, $a);
$D = static fn (int $m, string $t, array $a = []) => tdata($m, $t, $a) ?? [];
$idset = static function (array $rows, string $k): array { $x = array_map('intval', array_column($rows, $k)); sort($x); return $x; };
$sorted = static function (array $x): array { sort($x); return $x; };

echo "1. Every tool of the sweep answers (Priya)\n";
$bad = [];
$expectError = ['account_tickets' => 'no_connection', 'leaderboard' => 'managers_only', 'reminders_due' => 'managers_only', 'mailbox_health' => 'managers_only', 'key_usage_summary' => 'managers_only', 'tombstones' => 'managers_only'];
foreach (sweep($w) as [$t, $a]) {
    $r = $T(PRIYA, $t, $a);
    $want = $expectError[$t] ?? null;
    if ($want === null ? $r['error'] || $r['data'] === null : $r['code'] !== $want) { $bad[] = $t . ' → ' . ($r['code'] ?? substr($r['text'], 0, 60)); }
}
ok($bad === [], count(sweep($w)) . ' tools: each answers, or says in a code why not' . ($bad ? ' — ' . implode('; ', $bad) : ''));

echo "2. Leads and prospecting\n";
$all = $R(PRIYA, 'find_leads', ['limit' => 100]);
ok(!in_array($w['lead_tomb'], $idset($all, 'lead_id'), true) && count($all) === 6, 'find_leads: six live leads, the tombstoned one not among them');
ok($idset($R(PRIYA, 'find_leads', ['status' => ['working']]), 'lead_id') === [$w['lead_work']], 'status working → Wanda');
ok($sorted($idset($R(PRIYA, 'find_leads', ['owner' => 'none']), 'lead_id')) === $sorted([$w['lead_inbox'], $w['lead_prop']]), 'owner none → the unowned leads');
ok(!in_array($w['lead_inbox'], $idset($R(PRIYA, 'find_leads', ['owner' => 'me']), 'lead_id'), true) && in_array($w['lead_work'], $idset($R(PRIYA, 'find_leads', ['owner' => 'me']), 'lead_id'), true), 'owner me → Priya\'s own');
ok($sorted($idset($R(PRIYA, 'find_leads', ['source' => 'Website']), 'lead_id')) === $sorted([$w['lead_work'], $w['lead_dup']]), 'source Website (by name) → the two');
ok($idset($R(PRIYA, 'find_leads', ['campaign' => 'p4 Spring Push']), 'lead_id') === [$w['lead1']], 'campaign by name → the lead in it');
ok($idset($R(PRIYA, 'find_leads', ['untouched_days' => 90]), 'lead_id') === [$w['lead_old']], 'untouched 90 days → the old lead');
ok($idset($R(PRIYA, 'find_leads', ['proposed' => true]), 'lead_id') === [$w['lead_prop']], 'proposed → the form\'s lead');
ok($R(PRIYA, 'find_leads', ['sort' => 'score'])[0]['lead_id'] === $w['lead_work'], 'sort by score puts the scored lead first');
ok($T(PRIYA, 'find_leads', ['source' => 'No Such Source'])['code'] === 'not_found', 'an unknown source is not_found');
$p1 = $T(PRIYA, 'find_leads', ['limit' => 3, 'offset' => 0])['data'];
$p2 = $T(PRIYA, 'find_leads', ['limit' => 3, 'offset' => 3])['data'];
ok($p1['total'] === 6 && $p1['count'] === 3 && $p1['truncated'] === true && $p2['count'] === 3 && array_intersect($idset($p1['rows'], 'lead_id'), $idset($p2['rows'], 'lead_id')) === [], 'paging: total 6, a page of 3, truncated, the next page disjoint');
ok(count($R(PRIYA, 'find_leads', ['q' => 'SMOKE Initech'])) === 1 && $R(PRIYA, 'find_leads', ['q' => 'SMOKE Initech'])[0]['lead_id'] === $w['lead1'], 'q alone resolves a lead by company');
ok(count($R(PRIYA, 'find_leads', ['q' => 'Peter Gibbons · SMOKE Initech'])) === 1, 'and by its exact label — the resolver gets ONE row');
$g = $D(PRIYA, 'get_lead', ['lead' => $w['lead_work']]);
ok(($g['lead']['company'] ?? '') === 'p4 Workco' && array_key_exists('account_id', $g['converted'] ?? []) && $g['converted']['account_id'] === null && $idset($g['duplicates'] ?? [], 'other_id') === [$w['lead_dup']] && ($g['notes_count'] ?? -1) === 0, 'get_lead: the fields, nothing converted, its duplicate named');
$in = $R(PRIYA, 'leads_inbox', []);
ok($sorted($idset($in, 'lead_id')) === $sorted([$w['lead_inbox'], $w['lead_prop']]) && (find_row($in, 'lead_id', $w['lead_prop'])['proposed_from'] ?? '') === 'mailbox' && find_row($in, 'lead_id', $w['lead_inbox'])['proposed_from'] === null, 'leads_inbox: the unowned and the proposed — the proposed one says it came by the mailbox');
$un = $R(PRIYA, 'leads_untouched', ['days' => 30]);
ok(find_row($un, 'lead_id', $w['lead_old'])['days'] >= 120 && find_row($un, 'lead_id', $w['lead_work']) === null, 'leads_untouched: the 120-day lead, with its days');
$sp = $R(PRIYA, 'source_performance', ['from' => $back, 'to' => $today]);
ok(count($sp) === 7 && (int) find_row($sp, 'source_name', 'Website')['leads'] === 2 && is_string(find_row($sp, 'source_name', 'Website')['won_value']), 'source_performance: a row per source, Website with its two leads');
ok($R(PRIYA, 'source_performance', ['from' => $today, 'to' => $back]) === $sp, 'a reversed window is swapped, as the screens do');
$du = $R(PRIYA, 'find_duplicates', ['kind' => 'lead']);
ok(count($du) === 1 && $du[0]['matched_on'] === 'email' && $du[0]['a_label'] === 'Wanda Working · p4 Workco', 'find_duplicates: the pair, with labels and what matched');
ok($R(PRIYA, 'find_duplicates', ['kind' => 'account']) === [] && $T(PRIYA, 'find_duplicates', ['kind' => 'deal'])['code'] === 'invalid_argument', 'accounts have none; a deal is not a kind');
$im = $R(PRIYA, 'find_imports', []);
ok(count($im) === 1 && $im[0]['rows_created'] === 2 && $im[0]['rows_skipped'] === 1 && $im[0]['kind'] === 'leads_csv', 'find_imports: Priya\'s import with its counts');
ok($R(DANA, 'find_imports', []) === [] && count($R(MARCO, 'find_imports', [])) === 1, 'Dana sees none of it, Marco (a manager) sees it');
$gi = $D(PRIYA, 'get_import', ['import' => $w['imp']]);
ok(($gi['mapping']['email'] ?? '') === 'Email' && ($gi['log'] ?? '') === 'p4 import log', 'get_import: the mapping and the log');
ok($T(DANA, 'get_import', ['import' => $w['imp']])['code'] === 'not_found', 'another seller\'s import is not_found');
ok(count($R(PRIYA, 'import_rows', ['import' => $w['imp']])) === 3 && count($R(PRIYA, 'import_rows', ['import' => $w['imp'], 'result' => 'skipped'])) === 1 && $T(PRIYA, 'import_rows', ['import' => $w['imp'], 'result' => 'bogus'])['code'] === 'invalid_argument', 'import_rows: three rows, one skipped; a bogus result is refused');
$lists = $R(PRIYA, 'find_lists', []);
ok(count($lists) === 3 && count($R(DANA, 'find_lists', [])) === 2 && find_row($R(DANA, 'find_lists', []), 'name', 'p4 Priya private list') === null, 'find_lists: Priya\'s three; Dana sees the two shared, not Priya\'s private list');
ok(count($R(PRIYA, 'find_lists', ['q' => 'p4 Smart new leads'])) === 1 && count($R(PRIYA, 'find_lists', ['kind' => 'static', 'record_kind' => 'contact'])) === 1, 'q resolves a list; kind and record_kind filter');
$lm = $T(PRIYA, 'list_members', ['list' => 'p4 Smart new leads'])['data'];
ok($lm['record_kind'] === 'lead' && $lm['total'] === (int) $D(PRIYA, 'find_leads', ['status' => ['new']])['total'] && $lm['total'] === 5, 'list_members of a smart list: the live members — what find_leads status new says (5)');
ok($T(PRIYA, 'list_members', ['list' => 'p4 Static contacts'])['data']['total'] === 1 && $T(DANA, 'list_members', ['list' => 'p4 Static contacts'])['data']['total'] === 2, 'a static list: Priya sees Dana Reyes (the restricted contact is hidden from her), Dana sees both');
$sg = $T(PRIYA, 'segment_preview', ['record_kind' => 'lead', 'filters' => ['status' => 'new', 'owner' => 'none'], 'limit' => 1])['data'];
ok($sg['count'] === 2 && count($sg['sample']) === 1, 'segment_preview: how many (2) and a sample of one');
$sg = $T(PRIYA, 'segment_preview', ['record_kind' => 'contact', 'filters' => ['opt_out' => 'email']])['data'];
ok($sg['count'] === 1 && $sg['sample'][0]['name'] === 'Pat Umbra', 'a contact segment: opted out of email → Pat Umbra');
$sg = $T(PRIYA, 'segment_preview', ['record_kind' => 'deal', 'filters' => ['status' => 'open', 'min_value' => 20000]])['data'];
ok($sg['count'] === 1 && $sg['sample'][0]['deal_id'] === $w['deal1'], 'a deal segment: open and worth 20,000 or more → the Acme deal');
$sg = $T(PRIYA, 'segment_preview', ['record_kind' => 'lead', 'filters' => ['made_up_key' => 'x']])['data'];
ok($sg['count'] === 6, 'an unknown filter key is ignored (as the screens\' parsers drop it)');

echo "3. Accounts and contacts\n";
ok($sorted($idset($R(PRIYA, 'find_accounts', ['kind' => ['customer']]), 'account_id')) === $sorted([$w['acme'], $w['umbrella']]), 'find_accounts kind customer → Acme and Umbrella');
ok($idset($R(PRIYA, 'find_accounts', ['tag' => 'p4-vip']), 'account_id') === [$w['acme']] && $idset($R(PRIYA, 'find_accounts', ['country' => 'us']), 'account_id') === [$w['umbrella']], 'tag and country (case-insensitive)');
ok($idset($R(PRIYA, 'find_accounts', ['untouched_days' => 30]), 'account_id') === [$w['umbrella']] && $idset($R(PRIYA, 'find_accounts', ['has_open_deals' => true]), 'account_id') === [$w['acme']], 'untouched 30 days → Umbrella; with open deals → Acme');
ok($R(PRIYA, 'find_accounts', ['sort' => 'open_value'])[0]['account_id'] === $w['acme'] && is_string($R(PRIYA, 'find_accounts', [])[0]['open_deals_value']), 'sort by open value; amounts are strings');
ok(count($R(PRIYA, 'find_accounts', ['q' => 'p4 Umbrella Retail'])) === 1 && count($R(PRIYA, 'find_accounts', ['q' => 'umbrella.p4.example.invalid'])) === 1, 'q resolves an account by name or by domain');
$ga = $D(PRIYA, 'get_account', ['account' => 'SMOKE Acme Industries']);
ok($ga['account']['owner_name'] === 'SMOKE Priya' && $ga['primary_contact']['name'] === 'Dana Reyes' && isset($ga['next_step']['subject']) && !isset($ga['ledger']), 'get_account: owner named, the primary contact, the next step; no ledger unless asked');
$ga = $D(PRIYA, 'get_account', ['account' => $w['acme'], 'with_ledger' => true]);
ok(($ga['ledger']['error']['code'] ?? '') === 'no_connection', 'with_ledger and no approved connection: the account is answered and the ledger says no_connection');
ok(($D(PRIYA, 'account_contacts', ['account' => $w['acme']])['rows'][0]['name'] ?? '') === 'Dana Reyes', 'account_contacts: Dana Reyes, primary first');
$ad = $R(PRIYA, 'account_deals', ['account' => $w['acme']]);
ok(count($ad) === 5 && $ad[0]['status'] === 'open' && $ad[count($ad) - 1]['status'] !== 'open', 'account_deals: five, the open ones first');
ok($idset($R(PRIYA, 'account_deals', ['account' => $w['acme'], 'status' => ['won']]), 'deal_id') === [$w['deal_won']], 'account_deals status won → the won one');
$au = $R(PRIYA, 'accounts_untouched', ['days' => 30]);
ok(count($au) === 1 && $au[0]['name'] === 'p4 Umbrella Retail' && $au[0]['days'] >= 59, 'accounts_untouched: Umbrella, 60 days');
ok($idset($R(PRIYA, 'find_contacts', ['opt_out' => 'email']), 'contact_id') === [$w['pat']] && $idset($R(PRIYA, 'find_contacts', ['role' => 'decision_maker']), 'contact_id') === [$w['pat']], 'find_contacts: opted out of email → Pat; role decision_maker → Pat');
ok($idset($R(PRIYA, 'find_contacts', ['q' => 'elsewhere.p4']), 'contact_id') === [$w['pat']], 'q finds a person by their SECOND address');
ok($idset($R(PRIYA, 'find_contacts', ['account' => 'SMOKE Acme Industries']), 'contact_id') === [$w['dana_c']] && $sorted($idset($R(PRIYA, 'find_contacts', ['lifecycle' => ['customer']]), 'contact_id')) === $sorted([$w['dana_c'], $w['pat']]), 'by account name; by lifecycle');
ok(count($R(PRIYA, 'find_contacts', ['q' => 'Dana Reyes'])) === 1, 'q resolves a contact by name');
$gc = $D(PRIYA, 'get_contact', ['contact' => 'pat@umbrella.p4.example.invalid']);
ok($gc['contact']['name'] === 'Pat Umbra' && count($gc['emails']) >= 2 && $gc['account']['name'] === 'p4 Umbrella Retail' && $gc['deals'] === [], 'get_contact by email: every address, the account, no deals');
$gd = $D(PRIYA, 'get_contact', ['contact' => $w['dana_c']]);
ok(count($gd['deals']) >= 1 && isset($gd['deals'][0]['role']) && isset($gd['next_step']), 'get_contact: Dana\'s deals with her role, the next step');
$cu = $R(PRIYA, 'contacts_untouched', ['days' => 1]);
ok($cu === [] || isset($cu[0]['days']), 'contacts_untouched answers rows with days');
$ud = $R(PRIYA, 'upcoming_dates', ['days' => 30]);
ok(count($ud) === 1 && $ud[0]['kind'] === 'birthday' && $ud[0]['on_date'] === date('Y-m-d', time() + 10 * 86400), 'upcoming_dates: Pat\'s birthday in ten days');
ok($R(PRIYA, 'upcoming_dates', ['days' => 5]) === [], 'and not within five');
ok(count($R(PRIYA, 'find_attachments', ['kind' => 'deal', 'record' => 'SMOKE Acme — 20 seats'])) === 1 && $T(PRIYA, 'find_notes', ['kind' => 'issuer', 'record' => 1])['code'] === 'invalid_argument', 'attachments by deal name; a kind outside the four is refused');

echo "4. Pipeline and deals\n";
ok(count($R(PRIYA, 'find_pipelines', [])) === 2 && count($R(PRIYA, 'find_pipelines', ['q' => 'renewals'])) === 1 && count($R(PRIYA, 'find_pipelines', ['q' => 'New business'])) === 1, 'find_pipelines: two; q resolves by key or name');
$st = $R(PRIYA, 'find_stages', ['pipeline' => 'New business']);
ok(count($st) === 6 && $st[0]['name'] === 'Qualification' && $st[0]['position'] < $st[1]['position'] && count($R(PRIYA, 'find_stages', ['pipeline' => $w['pipe'], 'kind' => 'won'])) === 1, 'find_stages: six in order; kind won → one');
ok(count($R(PRIYA, 'find_stages', ['pipeline' => $w['pipe'], 'q' => 'Proposal'])) === 1, 'q resolves a stage within its pipeline');
$ps = $T(PRIYA, 'pipeline_summary', [])['data'];
$open = (float) sql_as(26, "SELECT COALESCE(sum(value), 0) AS v FROM mcp_deals WHERE status = 'open' AND pipeline_id = {$w['pipe']}")[0]['v'];
$sum = array_sum(array_map(fn ($r) => (float) $r['value'], array_filter($ps['rows'], fn ($r) => $r['kind'] === 'open')));
ok(abs($sum - $open) < 0.01 && $ps['currency'] === 'USD' && (int) find_row($ps['rows'], 'stage_name', 'Proposal')['rotting'] === 1, "pipeline_summary: the stages add up to the open value ($sum), the rotting deal is counted in Proposal");
$ps2 = $T(PRIYA, 'pipeline_summary', ['owner' => 'Marco'])['data'];
$o = static fn (array $d) => array_sum(array_column(array_filter($d['rows'], fn ($r) => $r['kind'] === 'open'), 'deals'));
ok($o($ps2) === 0 && $o($ps) === 3, 'pipeline_summary by owner: Marco holds no open deal here; the whole pipeline holds three');
$fc = $T(PRIYA, 'forecast', ['months' => 3, 'by' => 'seller'])['data'];
$thisMonth = find_row($fc['rows'], 'month', $monthStart);
ok($fc['currency'] === 'USD' && $thisMonth !== null && $thisMonth['open_value'] === '24000.00' && $thisMonth['won_value'] === '5000.00' && $thisMonth['quota'] === '20000.00', 'forecast: this month\'s open 24,000.00, won 5,000.00 and the quota 20,000.00 — strings');
ok(count($R(MARCO, 'forecast', ['months' => 1, 'by' => 'stage'])) >= 1 && $T(PRIYA, 'forecast', ['months' => 99])['code'] === 'invalid_argument' && $T(PRIYA, 'forecast', ['by' => 'region'])['code'] === 'invalid_argument', 'by stage; months and by are validated');
$fu = $R(PRIYA, 'funnel', ['from' => $back, 'to' => $today]);
ok(count($fu) >= 3 && isset($fu[0]['entered'], $fu[0]['moved_on'], $fu[0]['median_days']), 'funnel: per stage entered, moved on, lost, still here');
$wr = $R(PRIYA, 'win_rate', ['from' => $back, 'to' => $today, 'by' => 'seller']);
ok((int) find_row($wr, 'row_id', PRIYA)['won'] === 1 && (int) find_row($wr, 'row_id', PRIYA)['lost'] === 1 && abs((float) find_row($wr, 'row_id', PRIYA)['win_rate'] - 50.0) < 0.01, 'win_rate by seller: Priya won one and lost one: 50%');
ok(count($R(PRIYA, 'win_rate', ['from' => $back, 'to' => $today, 'by' => 'source'])) >= 1 && count($R(PRIYA, 'win_rate', ['from' => $back, 'to' => $today, 'by' => 'pipeline'])) >= 1 && $T(PRIYA, 'win_rate', ['from' => $back, 'to' => $today, 'by' => 'x'])['code'] === 'invalid_argument', 'by source and pipeline; others refused');
$ct = $T(PRIYA, 'cycle_time', ['from' => $back, 'to' => $today])['data'];
ok(count($ct['by_seller']) >= 1 && ((int) $ct['overall']['deals']) >= 2, 'cycle_time: per seller and overall (two deals won in the window)');
$ar = $R(PRIYA, 'deals_at_risk', []);
ok(find_row($ar, 'deal_id', $w['deal_rot']) !== null && find_row($ar, 'deal_id', $w['deal2']) !== null, 'deals_at_risk: the rotting deal and the one with no next step');
$only = $R(PRIYA, 'deals_at_risk', ['reason' => [find_row($ar, 'deal_id', $w['deal2'])['reason']]]);
ok($only !== [] && count($only) <= count($ar), 'filtered by reason');
ok($sorted($idset($R(PRIYA, 'deals_without_next_step', []), 'deal_id')) === $sorted([$w['deal2'], $w['deal_rot']]), 'deals_without_next_step: the two open deals with no open activity');
$rot = $R(PRIYA, 'deals_rotting', []);
ok($idset($rot, 'deal_id') === [$w['deal_rot']] && $rot[0]['days_in_stage'] >= 199, 'deals_rotting: the 200-day deal');
$od = $R(PRIYA, 'find_deals', ['status' => ['open']]);
ok($sorted($idset($od, 'deal_id')) === $sorted([$w['deal1'], $w['deal2'], $w['deal_rot']]) && count($R(PRIYA, 'find_deals', ['limit' => 100])) === 6, 'find_deals: three open; every status six (the restricted one is not among them)');
ok($idset($R(PRIYA, 'find_deals', ['status' => ['won']]), 'deal_id') !== [] && $idset($R(PRIYA, 'find_deals', ['status' => ['lost']]), 'deal_id') === [$w['deal_lost']], 'by status won / lost');
ok($sorted($idset($R(PRIYA, 'find_deals', ['account' => 'SMOKE Acme Industries']), 'deal_id')) === $sorted([$w['deal1'], $w['deal2'], $w['deal_won'], $w['deal_lost'], $w['deal_rot']]), 'by account name');
ok($sorted($idset($R(PRIYA, 'find_deals', ['contact' => 'dana.reyes@acme.example.invalid']), 'deal_id')) === $sorted([$w['deal1'], $w['deal_rot']]), 'by contact (by email): the two deals she is on');
ok($idset($R(PRIYA, 'find_deals', ['close' => 'this_month', 'status' => ['open']]), 'deal_id') === [$w['deal1']] && $idset($R(PRIYA, 'find_deals', ['min_value' => 20000, 'status' => ['open']]), 'deal_id') === [$w['deal1']], 'closing this month; at least 20,000');
ok($idset($R(PRIYA, 'find_deals', ['tag' => 'p4-vip']), 'deal_id') === [$w['deal1']] && $sorted($idset($R(PRIYA, 'find_deals', ['no_next_step' => true]), 'deal_id')) === $sorted([$w['deal2'], $w['deal_rot']]) && $idset($R(PRIYA, 'find_deals', ['rotting' => true]), 'deal_id') === [$w['deal_rot']], 'by tag, no next step, rotting');
ok(count($R(PRIYA, 'find_deals', ['team' => 'Sales', 'status' => ['open']])) === 3 && $R(PRIYA, 'find_deals', ['team' => 'Partnerships', 'status' => ['open']]) === [], 'by team (Sales\' members own the three; Partnerships none visible)');
ok($R(PRIYA, 'find_deals', ['sort' => 'value', 'status' => ['open']])[0]['deal_id'] === $w['deal1'] && count($R(PRIYA, 'find_deals', ['q' => 'SMOKE Acme — 20 seats'])) === 1 && count($R(PRIYA, 'find_deals', ['q' => 'D-000001'])) === 1, 'sort by value; q resolves a deal by title or by number');
ok($T(PRIYA, 'find_deals', ['stage' => ['No Such Stage']])['code'] === 'not_found' && count($R(PRIYA, 'find_deals', ['stage' => ['Qualification'], 'status' => ['open']])) === 2 && $T(PRIYA, 'find_deals', ['close' => 'someday'])['code'] === 'invalid_argument', 'by stage name; an unknown stage and a bad window are refused');
$gd = $D(PRIYA, 'get_deal', ['deal' => 'D-000001']);
ok(count($gd['contacts']) === 1 && count($gd['products']) === 2 && $gd['stage']['name'] === 'Qualification' && isset($gd['next_step']['subject']) && $gd['notes_count'] === 1 && $gd['attachments_count'] === 1 && is_array($gd['missing_for_next_stage']), 'get_deal by number: contacts, product lines, the stage, the next step, the counts');
$gd2 = $D(PRIYA, 'get_deal', ['deal' => $w['deal2']]);
ok(is_array($gd2['missing_for_next_stage']), 'and what the next stage still requires');
ok(count($R(PRIYA, 'deal_history', ['deal' => $w['deal_won']])) >= 2, 'deal_history: the moves of a won deal');
$dp = $T(PRIYA, 'deal_products', ['deal' => $w['deal1']])['data'];
ok($dp['total'] === '24000.00' && $dp['currency'] === 'USD' && $dp['rows'][0]['line_total'] === '20000.00' && $dp['rows'][0]['unit_price'] === '1000.00', 'deal_products: the lines and the total as money strings');
ok(count($R(PRIYA, 'deal_contacts', ['deal' => $w['deal1']])) === 1, 'deal_contacts');
$dc = $R(PRIYA, 'deals_closed', ['from' => $monthStart, 'to' => $today]);
